import sys


def main() -> None:
    input_stream = sys.stdin
    first_line = input_stream.readline()
    if not first_line:
        return

    count = int(first_line)
    if count == 0:
        return

    votes: dict[str, int] = {}
    for _ in range(count):
        name = input_stream.readline().rstrip("\n")
        votes[name] = votes.get(name, 0) + 1

    winner = min(votes, key=lambda name: (-votes[name], name))
    print(winner, votes[winner])


if __name__ == "__main__":
    main()

