use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.split('\n');
    let first_line = lines.next().unwrap_or("").trim_end_matches('\r');
    let n: usize = first_line.trim().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let mut prefix = lines
        .next()
        .unwrap_or("")
        .trim_end_matches('\r')
        .as_bytes()
        .to_vec();

    for _ in 1..n {
        let line = lines.next().unwrap_or("").trim_end_matches('\r');
        let bytes = line.as_bytes();
        let common_len = prefix
            .iter()
            .zip(bytes.iter())
            .take_while(|(left, right)| left == right)
            .count();
        prefix.truncate(common_len);
    }

    println!("{}", String::from_utf8(prefix).unwrap());
}

