def main() -> None:
    values = sys.stdin.buffer
    first_line = values.readline()
    if not first_line:
        return

    count = int(first_line)
    if count == 0:
        print(0)
        return

    previous = int(values.readline())
    current_run = 1
    longest_run = 1

    for _ in range(count - 1):
        current = int(values.readline())
        if current > previous:
            current_run += 1
            if current_run > longest_run:
                longest_run = current_run
        else:
            current_run = 1
        previous = current

    print(longest_run)


if __name__ == "__main__":
    main()

