source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i64> = values
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut sum: i64 = numbers[..k].iter().sum();
    let mut output = sum.to_string();

    for end in k..n {
        sum += numbers[end] - numbers[end - k];
        output.push(',');
        output.push_str(&sum.to_string());
    }

    println!("{output}");
}

source_texts.plurality_winner:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    let mut counts = BTreeMap::new();

    for name in values.take(n) {
        *counts.entry(name).or_insert(0usize) += 1;
    }

    if let Some((name, count)) = counts
        .iter()
        .max_by(|(name_a, count_a), (name_b, count_b)| {
            count_a.cmp(count_b).then_with(|| name_b.cmp(name_a))
        })
    {
        println!("{name} {count}");
    }
}

