import sys


def main() -> None:
    text = sys.stdin.readline().rstrip("\n")
    if text.endswith("\r"):
        text = text[:-1]

    if not text:
        print()
        return

    groups = []
    current = text[0]
    count = 1

    for character in text[1:]:
        if character == current:
            count += 1
        else:
            groups.append(f"{current}:{count}")
            current = character
            count = 1

    groups.append(f"{current}:{count}")
    print(",".join(groups))


if __name__ == "__main__":
    main()

