source_texts.rotate_words_left:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();

    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let k: usize = lines.next().unwrap_or("0").parse().unwrap();
    let words: Vec<&str> = lines.take(n).collect();

    if n == 0 {
        println!();
        return;
    }

    let shift = k % n;
    let rotated = words[shift..]
        .iter()
        .chain(words[..shift].iter())
        .copied()
        .collect::<Vec<_>>()
        .join("|");
    println!("{rotated}");
}

