import sys


def main() -> None:
    input_line = sys.stdin.readline
    n = int(input_line())

    if n == 0:
        print(0)
        return

    previous = int(input_line())
    current_length = 1
    longest_length = 1

    for _ in range(n - 1):
        value = int(input_line())
        if value > previous:
            current_length += 1
            if current_length > longest_length:
                longest_length = current_length
        else:
            current_length = 1
        previous = value

    print(longest_length)


if __name__ == "__main__":
    main()

