use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let mut current_start: i64 = values.next().unwrap().parse().unwrap();
    let mut current_end: i64 = values.next().unwrap().parse().unwrap();
    let mut merged = Vec::new();

    for _ in 1..n {
        let start: i64 = values.next().unwrap().parse().unwrap();
        let end: i64 = values.next().unwrap().parse().unwrap();
        if start <= current_end {
            current_end = current_end.max(end);
        } else {
            merged.push(format!("{current_start}:{current_end}"));
            current_start = start;
            current_end = end;
        }
    }

    merged.push(format!("{current_start}:{current_end}"));
    println!("{}", merged.join(","));
}

