import sys


n = int(sys.stdin.readline())
lines = [sys.stdin.readline().rstrip("\n") for _ in range(n)]

if not lines:
    print()
else:
    prefix = lines[0]
    for line in lines[1:]:
        limit = min(len(prefix), len(line))
        index = 0
        while index < limit and prefix[index] == line[index]:
            index += 1
        prefix = prefix[:index]
        if not prefix:
            break
    print(prefix)

