import sys


def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    words = lines[1:1 + n]

    if n == 0:
        print()
        return

    prefix = words[0]
    for word in words[1:]:
        limit = min(len(prefix), len(word))
        index = 0
        while index < limit and prefix[index] == word[index]:
            index += 1
        prefix = prefix[:index]
        if not prefix:
            break

    print(prefix)


if __name__ == "__main__":
    main()

