def main():
    text = sys.stdin.readline().rstrip("\n")

    if not text:
        print()
        return

    groups = []
    current = text[0]
    count = 1

    for letter in text[1:]:
        if letter == current:
            count += 1
        else:
            groups.append(f"{current}:{count}")
            current = letter
            count = 1
    groups.append(f"{current}:{count}")

    print(",".join(groups))


