        .max_by(|(name_a, count_a), (name_b, count_b)| {
            count_a.cmp(count_b).then_with(|| name_b.cmp(name_a))
        })
    {
        println!("{} {}", name, count);
    }
}

sources.rotate_words_left:
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let n: usize = lines.next().unwrap().unwrap().trim().parse().unwrap();
    let k: usize = lines.next().unwrap().unwrap().trim().parse().unwrap();
    let words: Vec<String> = lines.take(n).map(|line| line.unwrap()).collect();

    if n == 0 {
        println!();
        return;
    }
    let offset = k % n;
    let rotated: Vec<&str> = words[offset..]
        .iter()
        .chain(words[..offset].iter())
        .map(String::as_str)
        .collect();
    println!("{}", rotated.join("|"));
}

sources.run_length_encoding:
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let line = stdin.lock().lines().next().map(Result::unwrap).unwrap_or_default();
    let mut characters = line.chars();
    let Some(mut current) = characters.next() else {
        println!();
        return;
    };

    let mut count = 1usize;
    let mut groups = Vec::new();
    for character in characters {
        if character == current {
            count += 1;
        } else {
            groups.push(format!("{}:{}", current, count));
            current = character;
            count = 1;
        }
    }
    groups.push(format!("{}:{}", current, count));
    println!("{}", groups.join(","));
}

sources.stable_word_deduplication:
use std::collections::HashSet;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let n: usize = lines.next().unwrap().unwrap().trim().parse().unwrap();
    let mut seen = HashSet::new();
    let mut retained = Vec::new();
    for line in lines.take(n) {
        let word = line.unwrap();
        if seen.insert(word.clone()) {
            retained.push(word);
        }
    }
    println!("{}", retained.join("|"));
}

