source_texts.longest_rising_run:
import sys


def main():
    lines = sys.stdin.buffer.read().splitlines()
    n = int(lines[0])
    values = [int(line) for line in lines[1:1 + n]]
    if not values:
        print(0)
        return
    longest = current = 1
    for previous, value in zip(values, values[1:]):
        if value > previous:
            current += 1
            longest = max(longest, current)
        else:
            current = 1
    print(longest)


if __name__ == "__main__":
    main()

source_texts.merge_sorted_intervals:
import sys


def main():
    lines = sys.stdin.buffer.read().splitlines()
    n = int(lines[0])
    intervals = [tuple(map(int, line.split())) for line in lines[1:1 + n]]
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    print(",".join(f"{start}:{end}" for start, end in merged))


if __name__ == "__main__":
    main()

source_texts.longest_common_prefix:
import sys


def main():
    lines = sys.stdin.buffer.read().splitlines()
    n = int(lines[0])
    texts = lines[1:1 + n]
    if not texts:
        print()
        return
    prefix = texts[0]
    for text in texts[1:]:
        limit = min(len(prefix), len(text))
        index = 0
        while index < limit and prefix[index] == text[index]:
            index += 1
        prefix = prefix[:index]
        if not prefix:
            break
    sys.stdout.buffer.write(prefix + b"\n")


if __name__ == "__main__":
    main()

source_texts.stable_word_deduplication:
import sys


def main():
    lines = sys.stdin.buffer.read().splitlines()
    n = int(lines[0])
    seen = set()
    retained = []
    for word in lines[1:1 + n]:
        if word not in seen:
            seen.add(word)
            retained.append(word)
    sys.stdout.buffer.write(b"|".join(retained) + b"\n")


if __name__ == "__main__":
    main()

