import sys


def main():
    text = sys.stdin.buffer.readline().rstrip(b"\r\n")
    if not text:
        print()
        return
    groups = []
    current = text[0]
    count = 1
    for letter in text[1:]:
        if letter == current:
            count += 1
        else:
