source_texts.rotate_words_left:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let k: usize = lines.next().unwrap().parse().unwrap();
    let words: Vec<&str> = lines.take(n).collect();

    if n == 0 {
        println!();
        return;
    }

    let shift = k % n;
    let rotated: Vec<&str> = words[shift..]
        .iter()
        .chain(words[..shift].iter())
        .copied()
        .collect();
    println!("{}", rotated.join("|"));
}

source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i128> = values.take(n).map(|s| s.parse().unwrap()).collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());
    for i in k..n {
        sum += numbers[i] - numbers[i - k];
        sums.push(sum.to_string());
    }
    println!("{}", sums.join(","));
}

