}

sources.merge_sorted_intervals:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let mut start: i128 = values.next().unwrap().parse().unwrap();
    let mut end: i128 = values.next().unwrap().parse().unwrap();
    let mut merged = Vec::new();

    for _ in 1..n {
        let next_start: i128 = values.next().unwrap().parse().unwrap();
        let next_end: i128 = values.next().unwrap().parse().unwrap();
        if next_start <= end {
            end = end.max(next_end);
        } else {
            merged.push(format!("{start}:{end}"));
            start = next_start;
            end = next_end;
        }
    }
    merged.push(format!("{start}:{end}"));
    println!("{}", merged.join(","));
}

sources.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i128> = values.take(n).map(|s| s.parse().unwrap()).collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());
    for i in k..n {
        sum += numbers[i] - numbers[i - k];
        sums.push(sum.to_string());
    }
    println!("{}", sums.join(","));
}

sources.plurality_winner:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut counts = BTreeMap::new();

    for name in lines.take(n) {
        *counts.entry(name).or_insert(0usize) += 1;
    }

    if let Some((name, count)) = counts.iter().max_by(|a, b| {
        a.1.cmp(b.1).then_with(|| b.0.cmp(a.0))
    }) {
        println!("{name} {count}");
    }
}

sources.rotate_words_left:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let k: usize = lines.next().unwrap().parse().unwrap();
    let words: Vec<&str> = lines.take(n).collect();

    if n == 0 {
        println!();
        return;
    }

    let shift = k % n;
    let rotated: Vec<&str> = words[shift..]
        .iter()
        .chain(words[..shift].iter())
        .copied()
        .collect();
    println!("{}", rotated.join("|"));
}

sources.run_length_encoding:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let line = input.lines().next().unwrap_or("");
    let mut chars = line.chars();
    let Some(mut current) = chars.next() else {
        println!();
        return;
    };

    let mut count = 1usize;
    let mut groups = Vec::new();
    for ch in chars {
        if ch == current {
            count += 1;
        } else {
            groups.push(format!("{current}:{count}"));
            current = ch;
            count = 1;
        }
    }
    groups.push(format!("{current}:{count}"));
    println!("{}", groups.join(","));
}

sources.stable_word_deduplication:
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut seen = HashSet::new();
    let mut retained = Vec::new();

    for word in lines.take(n) {
        if seen.insert(word) {
            retained.push(word);
        }
    }
    println!("{}", retained.join("|"));
}

